/* =============================================================================
   MSG-01 · Pantalla Lista de Hilos — panel de contenido.
   ============================================================================= */

.screen {
  min-width: 0;
}

.eyebrow {
  margin: 0 0 4px;
  font-family: var(--bw-font-title);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--bw-steel-mist);
}

.title {
  margin: 0 0 3px;
  font-family: var(--bw-font-title);
  font-size: 20px;
  font-weight: 700;
  color: var(--bw-deep-steel);
}

.subtitle {
  max-width: 560px;
  margin: 0 0 16px;
  font-size: 14px;
  line-height: 1.6;
  color: var(--bw-steel-mist);
}

.actionsArea {
  margin-bottom: 14px;
}

.actionsBar {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.searchWrap {
  position: relative;
  flex: 1;
  min-width: 220px;
  max-width: 300px;
  margin: 0;
}

.searchWrap i {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--bw-input-placeholder);
  font-size: 15px;
  pointer-events: none;
}

.searchInput {
  width: 100%;
  height: 36px;
  padding: 0 10px 0 32px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 5px;
  font-size: 13px;
  font-family: inherit;
  color: var(--bw-input-text);
  background: var(--bw-surface-mist);
  outline: none;
  transition: border-color 0.15s;
}

.searchInput:focus {
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
}

.searchInput::placeholder {
  color: var(--bw-input-placeholder);
}

.newContactBlock {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.btnPrimary {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 36px;
  padding: 0 18px;
  background: var(--bw-calibration-blue);
  border: 0;
  border-radius: 5px;
  color: var(--bw-warm-cream); /* sin token de blanco puro; crema es el más cercano */
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  font-family: inherit;
  white-space: nowrap;
  transition: opacity 0.12s;
}

.btnPrimary:hover:not(:disabled) {
  opacity: 0.88;
}

.btnPrimary:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.scopeNote {
  max-width: 220px;
  font-size: 11px;
  line-height: 1.4;
  color: var(--bw-steel-mist);
}

.threadCount {
  margin-left: auto;
  font-size: 12px;
  color: var(--bw-input-placeholder);
  white-space: nowrap;
}

.loading {
  padding: 20px 18px;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  font-size: 13px;
  color: var(--bw-steel-mist);
}

.alert {
  padding: 10px 12px;
  background: var(--bw-sensitive-bg);
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: 5px;
  font-size: 13px;
  color: var(--bw-sensitive-text);
}

.pagination {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 14px;
}

.pageBtn,
.pageCtrl {
  min-width: 30px;
  height: 30px;
  padding: 0 8px;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 4px;
  font-size: 12px;
  font-family: inherit;
  color: var(--bw-ink-steel);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: border-color 0.12s, color 0.12s;
}

.pageBtn:hover:not(:disabled),
.pageCtrl:hover:not(:disabled) {
  border-color: var(--bw-brass);
  color: var(--bw-brass);
}

.pageBtn:disabled,
.pageCtrl:disabled {
  cursor: default;
  opacity: 0.55;
}

.pageBtnActive,
.pageBtnActive:disabled {
  background: var(--bw-deep-steel);
  border-color: var(--bw-deep-steel);
  color: var(--bw-warm-cream);
  opacity: 1;
}

.pageGap {
  min-width: 18px;
  text-align: center;
  color: var(--bw-steel-mist);
}

