import { useEffect, useState, type FormEvent, type KeyboardEvent } from 'react';
import type { MemberProfile } from '../../lib/session';
import { fetchThreadPage, pageCount, type ThreadPage } from '../../lib/threads';
import { ThreadList } from './ThreadList';
import styles from './Messages.module.css';

/**
 * MSG-01 · Lista de Hilos — pantalla.
 *
 * Posee el estado de búsqueda y de página y llama a `fetchThreadPage` con la
 * organización del perfil. El listado en sí es presentacional (`ThreadList`).
 */

type LoadState =
  | { status: 'loading' }
  | { status: 'error'; error: unknown }
  | { status: 'ready'; page: ThreadPage };

interface MessagesProps {
  profile: MemberProfile;
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date | undefined;
  /**
   * F-118: firma pública cableada desde App.tsx. MSG-02 no existe todavía, así
   * que esta pantalla no navega a ningún sitio: solo transmite el id si alguien
   * le pasa un manejador.
   */
  onOpenThread?: ((threadId: string) => void) | undefined;
}

/** F-128: PostgREST rechaza con objeto plano { code, message }; String(e) daría
 *  "[object Object]". Se sacan code/message cuando existen y se pintan. */
function errorDetail(e: unknown): string {
  if (typeof e === 'object' && e !== null) {
    const record = e as Record<string, unknown>;
    const code = typeof record.code === 'string' ? record.code : '';
    const message = typeof record.message === 'string' ? record.message : '';
    if (code || message) return [code, message].filter(Boolean).join(' · ');
  }
  return e instanceof Error ? e.message : String(e);
}

/** Ventana de números de página: sin decenas de botones cuando el total es alto. */
function pageItems(current: number, total: number): (number | '…')[] {
  if (total <= 7) {
    return Array.from({ length: total }, (_, i) => i + 1);
  }
  const out: (number | '…')[] = [1];
  const start = Math.max(2, current - 1);
  const end = Math.min(total - 1, current + 1);
  if (start > 2) out.push('…');
  for (let p = start; p <= end; p += 1) out.push(p);
  if (end < total - 1) out.push('…');
  out.push(total);
  return out;
}

export function Messages({ profile, now = new Date(), onOpenThread }: MessagesProps) {
  const [searchInput, setSearchInput] = useState('');
  const [term, setTerm] = useState('');
  const [page, setPage] = useState(1);
  const [state, setState] = useState<LoadState>({ status: 'loading' });

  const openThread = onOpenThread ?? (() => {});

  useEffect(() => {
    let active = true;
    setState({ status: 'loading' });
    fetchThreadPage({ orgId: profile.orgId, search: term, page }).then(
      (result) => {
        if (active) setState({ status: 'ready', page: result });
      },
      (err: unknown) => {
        if (active) setState({ status: 'error', error: err });
      },
    );
    return () => {
      active = false;
    };
  }, [profile.orgId, term, page]);

  const pageData = state.status === 'ready' ? state.page : null;
  const totalThreads = pageData?.total ?? 0;
  const totalPages = pageData ? pageCount(pageData.total) : 1;

  const applySearch = () => {
    setPage(1);
    setTerm(searchInput.trim());
  };

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    applySearch();
  };

  const handleSearchKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      applySearch();
    }
  };

  const goToPage = (next: number) => {
    if (next >= 1 && next <= totalPages) setPage(next);
  };

  return (
    <div className={styles.screen}>
      <p className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</p>
      <h1 className={styles.title}>Hilos</h1>
      <p className={styles.subtitle}>
        Tus conversaciones con otros distribuidores. Todo el contenido está
        cifrado de extremo a extremo.
      </p>

      <div className={styles.actionsArea}>
        <div className={styles.actionsBar}>
          <form className={styles.searchWrap} role="search" onSubmit={handleSubmit}>
            <i className="ti ti-search" aria-hidden="true" />
            <input
              className={styles.searchInput}
              type="search"
              placeholder="Buscar por nombre de organización..."
              aria-label="Buscar por nombre de organización"
              value={searchInput}
              onChange={(event) => setSearchInput(event.target.value)}
              onKeyDown={handleSearchKeyDown}
            />
          </form>

          <div className={styles.newContactBlock}>
            <button type="button" className={styles.btnPrimary} disabled>
              <i className="ti ti-address-book" aria-hidden="true" />
              Nuevo contacto
            </button>
            {/* F-139: el nodo con el motivo visible del botón deshabilitado. */}
            <span className={styles.scopeNote} data-testid="directorio-scope">
              El Directorio de organizaciones queda fuera del MVP.
            </span>
          </div>

          {/* F-138: el contador de resultados lleva este testid. */}
          {pageData ? (
            <span className={styles.threadCount} data-testid="pag-info">
              {`${totalThreads.toLocaleString('es-ES')} hilos · Página ${page.toLocaleString(
                'es-ES',
              )} de ${totalPages.toLocaleString('es-ES')}`}
            </span>
          ) : null}
        </div>
      </div>

      {state.status === 'loading' ? (
        <div className={styles.loading} role="status">
          Cargando hilos…
        </div>
      ) : state.status === 'error' ? (
        /* F-127 + F-128: aviso con role="alert" que incluye el error real. */
        <div className={styles.alert} role="alert">
          No se pudieron cargar los hilos: {errorDetail(state.error)}
        </div>
      ) : pageData ? (
        <>
          <ThreadList threads={pageData.threads} now={now} onOpen={openThread} />

          <div className={styles.pagination}>
            <button
              type="button"
              className={styles.pageCtrl}
              aria-label="Página anterior"
              disabled={page <= 1}
              onClick={() => goToPage(page - 1)}
            >
              ‹
            </button>

            {pageItems(page, totalPages).map((item) =>
              item === '…' ? (
                <span key="…" className={styles.pageGap}>
                  …
                </span>
              ) : (
                <button
                  key={item}
                  type="button"
                  className={`${styles.pageBtn} ${item === page ? styles.pageBtnActive : ''}`}
                  aria-label={`Página ${item}`}
                  aria-current={item === page ? 'page' : undefined}
                  disabled={item === page}
                  onClick={() => goToPage(item)}
                >
                  {item}
                </button>
              ),
            )}

            <button
              type="button"
              className={styles.pageCtrl}
              aria-label="Página siguiente"
              disabled={page >= totalPages}
              onClick={() => goToPage(page + 1)}
            >
              ›
            </button>
          </div>
        </>
      ) : null}
    </div>
  );
}

