/* =============================================================================
   MSG-01 · Lista de hilos — filas y estado vacío.
   ============================================================================= */

.list {
  margin: 0;
  padding: 0;
  list-style: none;
  /* El mock usa blanco puro aquí; no hay token de blanco puro, así que se usa la
     superficie clara más próxima del sistema (--bw-surface-mist). */
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  overflow: hidden;
}

.row {
  border-bottom: 1px solid var(--bw-divider-mist);
}

.row:last-child {
  border-bottom: 0;
}

.rowOpen {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: auto auto;
  column-gap: 10px;
  row-gap: 4px;
  width: 100%;
  padding: 14px 18px;
  background: none;
  border: 0;
  border-radius: 0;
  font: inherit;
  text-align: left;
  color: inherit;
  cursor: pointer;
}

.rowOpen:hover {
  background: var(--bw-row-hover-tint);
}

.rowOpen:focus-visible {
  outline: 2px solid var(--bw-calibration-blue);
  outline-offset: -2px;
}

.rowTop {
  grid-column: 1;
  grid-row: 1;
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.threadOrg {
  font-size: 14px;
  font-weight: 500;
  color: var(--bw-deep-steel);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.countryBadge {
  flex-shrink: 0;
  font-family: var(--bw-font-mono);
  font-size: 10px;
  padding: 1px 6px;
  border-radius: 3px;
  background: var(--bw-cold-white);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-line-steel);
  white-space: nowrap;
}

.threadTs {
  grid-column: 2;
  grid-row: 1;
  justify-self: end;
  align-self: flex-start;
  font-family: var(--bw-font-mono);
  font-size: 10px;
  color: var(--bw-input-placeholder);
  white-space: nowrap;
}

.threadPreview {
  grid-column: 1;
  grid-row: 2;
  align-self: center;
  min-width: 0;
  font-size: 12px;
  color: var(--bw-steel-mist);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.stateBadge {
  grid-column: 2;
  grid-row: 2;
  justify-self: end;
  align-self: center;
  font-family: var(--bw-font-mono);
  font-size: 9px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 2px 7px;
  border-radius: 3px;
  white-space: nowrap;
}

.stateAbierto {
  background: var(--bw-badge-neutral-bg);
  border: 1px solid var(--bw-badge-neutral-border);
  color: var(--bw-steel-mist);
}

.stateInfo {
  background: var(--bw-chip-active-bg);
  /* No hay token de borde azul al 20%; --bw-chip-active-border (30%) es el más
     cercano del sistema. */
  border: 1px solid var(--bw-chip-active-border);
  color: var(--bw-calibration-blue);
}

.stateWarn {
  background: var(--bw-badge-warning-bg);
  border: 1px solid var(--bw-badge-warning-border);
  color: var(--bw-warning);
}

.stateSuccess {
  background: var(--bw-badge-success-bg);
  border: 1px solid var(--bw-badge-success-border);
  color: var(--bw-signal-green);
}

.stateCerrado {
  background: var(--bw-badge-neutral-bg);
  border: 1px solid var(--bw-badge-neutral-border-soft);
  color: var(--bw-input-placeholder);
  text-decoration: line-through;
}

/* ---------------------------------------------------------------------------
   Estado vacío — F-141: nunca dentro de un <ul>.
   --------------------------------------------------------------------------- */
.empty {
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  padding: 36px 18px;
  text-align: center;
}

.emptyText {
  max-width: 420px;
  margin: 0 auto;
  font-size: 14px;
  line-height: 1.6;
  color: var(--bw-steel-mist);
}

.emptyBtn {
  display: inline-flex;
  align-items: center;
  height: 36px;
  padding: 0 18px;
  margin-top: 14px;
  background: var(--bw-calibration-blue);
  border: 0;
  border-radius: 5px;
  color: var(--bw-warm-cream); /* sin token de blanco puro; crema es el más cercano */
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  font-family: inherit;
}

.emptyBtn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.emptyReason {
  margin: 6px 0 0;
  font-size: 12px;
  color: var(--bw-steel-mist);
}

