import {
  previewLabel,
  relativeTime,
  stateTone,
  type StateTone,
  type ThreadSummary,
} from '../../lib/threads';
import styles from './ThreadList.module.css';

/**
 * MSG-01 · Lista de hilos.
 *
 * Componente presentacional: recibe las filas ya ordenadas por el servidor y
 * avisa con el id al abrir una fila. No consulta datos ni pagina.
 */
const TONE_CLASS: Record<StateTone, string> = {
  neutral: styles.stateAbierto,
  info: styles.stateInfo,
  warn: styles.stateWarn,
  success: styles.stateSuccess,
  closed: styles.stateCerrado,
};

interface ThreadListProps {
  threads: ThreadSummary[];
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date | undefined;
  onOpen: (id: string) => void;
}

export function ThreadList({ threads, now = new Date(), onOpen }: ThreadListProps) {
  if (threads.length === 0) {
    // F-141: el estado vacío no vive dentro de un <ul>. Con threads vacío no puede
    // quedar ningún rol `listitem` en el documento.
    return (
      <div className={styles.empty}>
        <p className={styles.emptyText}>
          Todavía no tienes ninguna conversación. Usa el Directorio para contactar
          con otras organizaciones.
        </p>
        <button type="button" className={styles.emptyBtn} disabled>
          Ir al Directorio
        </button>
        <p className={styles.emptyReason}>El Directorio queda fuera del MVP.</p>
      </div>
    );
  }

  return (
    <ul className={styles.list}>
      {threads.map((thread) => {
        const tone = stateTone(thread.state);
        return (
          // F-131: el <li> conserva su rol implícito `listitem`. El elemento
          // pulsable es el <button> de dentro, nunca un role encima del <li>.
          <li key={thread.id} className={styles.row}>
            <button
              type="button"
              className={styles.rowOpen}
              onClick={() => onOpen(thread.id)}
            >
              <span className={styles.rowTop}>
                <span className={styles.threadOrg}>{thread.counterpartyName}</span>
                {thread.counterpartyCountry ? (
                  <span className={styles.countryBadge}>{thread.counterpartyCountry}</span>
                ) : null}
              </span>
              <span className={styles.threadTs}>
                {relativeTime(thread.lastItemAt, now)}
              </span>
              {/* Vista previa de METADATOS únicamente: nunca contenido descifrado. */}
              <span className={styles.threadPreview}>{previewLabel(thread.lastItem)}</span>
              <span className={`${styles.stateBadge} ${TONE_CLASS[tone]}`}>
                {thread.state}
              </span>
            </button>
          </li>
        );
      })}
    </ul>
  );
}
